-- Projects portfolio entries

create table "public"."projects" (
  "id" bigint primary key generated by default as identity,
  "name" varchar,
  "company" varchar,
  "type" "public"."Project Types",
  "image" varchar,
  "link" varchar,
  "user" uuid default gen_random_uuid(),
  "order" smallint,
  "description" text,
  "is_active" boolean not null default true,
  "skill_ids" integer[],
  "slug" varchar,
  "images" varchar[],
  constraint "projects_slug_key" unique ("slug")
);

alter table "public"."projects" add constraint "projects_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."projects" enable row level security;
create policy "Enable read access for all users" on "public"."projects" for select using (true);

grant all on "public"."projects" to postgres, anon, authenticated, service_role;
